import{demo}from './demo.js';import{validate}from './engine.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=(x,d=0)=>x==null?'—':Number(x).toLocaleString('ro-RO',{maximumFractionDigits:d});
let model=demo(),page='overview',selected='line-a',result=null,ranks={},baseline=null,busy=false,worker=null,history=[],future=[],hours=8,seed=42,saveOK=true;
try{const saved=localStorage.getItem('factory-studio-v1');if(saved){const p=JSON.parse(saved);validate(p);model=p;selected=model.lines[0].id}}catch{saveOK=false}
const names={overview:'Imagine de ansamblu',lines:'Editor de producție',simulation:'Simulare & bottleneck',scenarios:'Scenarii',architecture:'Arhitectură MOFLT',requirements:'Cerințe & trasabilitate',safety:'Safety register',about:'Capabilități & metodă'};
const navicons=['◫','⌘','◷','⇄','◇','☷','△','ⓘ'];
function toast(t){$('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),5000)}
function persist(){try{localStorage.setItem('factory-studio-v1',JSON.stringify(model));saveOK=true}catch{saveOK=false;toast('Salvarea locală nu este disponibilă. Exportă modelul JSON.')}}
function mutate(fn){const before=structuredClone(model);try{fn();validate(model);history.push(before);if(history.length>40)history.shift();future=[];result=null;ranks={};persist();render()}catch(e){model=before;toast(e.message)}}
function line(){return model.lines.find(l=>l.id===selected)||model.lines[0]}
function lr(id){return result?.lines.find(l=>l.lineId===id)}
function run(){if(busy)return;busy=true;render();const snap=structuredClone(model);worker=new Worker('worker.js',{type:'module'});worker.onmessage=({data})=>{busy=false;worker.terminate();worker=null;if(data.error)toast(data.error);else{result=data.result;ranks=data.ranks;toast('Simulare și analiză de sensibilitate finalizate.')}render()};worker.onerror=()=>{busy=false;worker?.terminate();worker=null;render();toast('Motorul de simulare a întâmpinat o eroare.')};worker.postMessage({model:snap,options:{hours,seed}})}
function controls(){return `<div class="controls"><label>Orizont <input id="hours" aria-label="Orizont ore" type="number" min="0.1" max="168" step="0.5" value="${hours}" ${busy?'disabled':''}> h</label><label>Seed <input id="seed" aria-label="Seed" type="number" min="0" max="2147483647" value="${seed}" ${busy?'disabled':''}></label><button class="primary" data-act="run" ${busy?'disabled':''}>${busy?'Se calculează…':'▷ Rulează simularea'}</button>${busy?'<button data-act="cancel">Anulează</button>':''}</div>`}
function stats(){const n=model.lines.reduce((a,l)=>a+l.stations.length,0);return `<div class="stats">${[['PRODUSE FINALIZATE',fmt(result?.done),result?`în ${hours} ore · toate liniile`:'rulează simularea'],['ÎN PROCES + AȘTEPTARE',fmt(result?.wip),'inclusiv coada externă de intrare'],['RESURSE MODELATE',fmt(n),`${model.lines.length} linii de producție`],['SCENARIU ACTIV',baseline?'Variantă':'Baseline',baseline?'comparare cu snapshot salvat':'date demonstrative editabile']].map(([a,b,c])=>`<div class="stat"><div class="small muted">${a}</div><div class="value">${b}</div><div class="tiny">${c}</div></div>`).join('')}</div>`}
function factory(lines=model.lines){return `<div class="factory">${lines.map(l=>{const r=lr(l.id),top=ranks[l.id]?.find(x=>x.gain>0)?.id;return `<div class="line-zone"><div class="zonetitle"><button class="linkbtn" data-line="${esc(l.id)}">${esc(l.name)} ↗</button><span>${r?fmt(r.throughput,1)+' buc/h':'Nesimulat'}</span></div><div class="flow">${l.stations.map((s,i)=>{const st=r?.stations.find(x=>x.id===s.id);return `${i?'<span class="arrow">→</span>':''}<button class="station ${s.id===top?'hot':''}" data-edit="${esc(s.id)}"><strong>${esc(s.name)}</strong><em>${fmt(s.cycle,1)} s · ${s.capacity} resursă${s.capacity>1?'e':''}</em><div class="progress"><i style="width:${st?st.busy*100:0}%"></i></div></button>`}).join('')}</div></div>`}).join('')}<div class="legend"><span><i class="dot"></i>Procesare</span><span><i class="dot amber"></i>Candidat confirmat prin sensibilitate</span><span>Click pe stație pentru editare</span></div></div>`}
function insight(){let candidates=model.lines.flatMap(l=>(ranks[l.id]||[]).filter(x=>x.gain>0).slice(0,1).map(x=>({...x,line:l,station:l.stations.find(s=>s.id===x.id)})));return `<div class="panel"><h2>Unde intervii prima dată?</h2>${!result?'<p class="muted small">Rulează simularea pentru a evalua efectul reducerii cu 20% a timpului fiecărei stații.</p>':candidates.length?candidates.map(c=>`<div class="insight"><strong>${esc(c.station.name)}</strong><p>${esc(c.line.name)}</p><strong>+${fmt(c.gain)} produse / ${hours} h</strong><p>cu timp de procesare −20%; restul modelului rămâne identic.</p><button class="linkbtn" data-edit="${esc(c.id)}">Examinează stația →</button></div>`).join(''):'<p class="muted small">Nicio reducere locală de 20% nu a crescut producția. Verifică alimentarea și constrângerile simultane.</p>'}<p class="small muted">Estimare dintr-o singură replicare. Sensibilitatea susține o ipoteză; nu este validare industrială.</p></div><div class="panel"><span class="eyebrow">MODEL DRIVEN</span><h3>De la misiune la echipament</h3><p class="small muted">Păstrează cerințele legate de funcții, componente și stații.</p><button data-page="architecture">Explorează MOFLT ↗</button></div>`}
function overview(){return `${stats()}<div class="panels"><div><div class="panel"><div class="panelhead"><h2>Harta producției</h2><span class="badge">ISA-95 · structură simplificată</span></div>${factory()}</div><div class="notice">Demo fictiv · Model DES serial, linii independente. Fluxul începe gol, cu sosiri periodice; variabilitatea este uniformă. Nu sunt încă modelate defectări, schimburi sau operatori partajați.</div></div><aside>${insight()}</aside></div>`}
function lineSelect(){return `<select id="line-select" aria-label="Linia selectată">${model.lines.map(l=>`<option value="${esc(l.id)}" ${l.id===line().id?'selected':''}>${esc(l.name)}</option>`).join('')}</select>`}
function editor(){const l=line();return `<div class="panel"><div class="panelhead"><div class="row">${lineSelect()}<button data-act="new-line">+ Linie</button></div><button data-act="new-station">+ Stație</button></div><div class="row"><label>Nume linie <input id="line-name" value="${esc(l.name)}"></label><label>Sosire o piesă la <input id="arrival" type="number" min="1" value="${l.arrival}"> secunde</label><button data-act="save-line">Salvează linia</button></div>${factory([l])}<p class="small muted">Ruta urmează ordinea stațiilor. Bufferul este coada de intrare; la prima stație coada externă este nelimitată. Capacitate = resurse paralele identice.</p><div class="tablewrap"><table><thead><tr><th>Stație</th><th>Ciclu (s)</th><th>Capacitate</th><th>Buffer (piese)</th><th>Variație ±</th><th>Ordine</th><th></th></tr></thead><tbody>${l.stations.map((s,i)=>`<tr><td><button class="linkbtn" data-edit="${esc(s.id)}">${esc(s.name)}</button></td><td>${s.cycle}</td><td>${s.capacity}</td><td>${i?s.buffer:'Extern ∞'}</td><td>${fmt(s.variation*100)}%</td><td><button data-move="${esc(s.id)}" data-dir="-1" ${i===0?'disabled':''}>↑</button> <button data-move="${esc(s.id)}" data-dir="1" ${i===l.stations.length-1?'disabled':''}>↓</button></td><td><button data-delete="${esc(s.id)}" class="danger">Șterge</button></td></tr>`).join('')}</tbody></table></div></div>`}
function chart(r){if(!r)return '';const max=Math.max(1,...r.series.map(x=>x.wip));const points=r.series.map(x=>`${40+x.t/hours*650},${155-x.wip/max*125}`).join(' ');return `<svg class="chart" role="img" aria-label="Evoluția WIP inclusiv coada de intrare" viewBox="0 0 720 190"><line x1="40" y1="155" x2="690" y2="155" stroke="#dce5df"/><text x="5" y="35">${fmt(max)}</text><text x="12" y="158">0</text><text x="40" y="181">0 h</text><text x="660" y="181">${hours} h</text><polyline fill="none" stroke="#4c9575" stroke-width="2.5" points="${points}"/></svg>`}
function simulation(){const l=line(),r=lr(l.id);return `<div class="row">${lineSelect()}<button data-act="csv" ${r?'':'disabled'}>↓ Export rezultate CSV</button></div>${!r?'<div class="panel empty">Rulează simularea pentru a vedea performanța și constrângerile.</div>':`<div class="stats">${[['Producție / oră',fmt(r.throughput,1)],['Lead time mediu',r.leadMean==null?'—':fmt(r.leadMean/60,1)+' min'],['Lead time p95',r.leadP95==null?'—':fmt(r.leadP95/60,1)+' min'],['WIP final',fmt(r.wip)]].map(([a,b])=>`<div class="stat"><span class="muted small">${a}</span><div class="value">${b}</div></div>`).join('')}</div><div class="panel"><h2>Stări și sensibilitate pe stație</h2><p class="small muted">Lead time este calculat numai pentru piesele finalizate. Idle include lipsa materialului; bufferul extern poate crește dacă cererea depășește capacitatea.</p><div class="tablewrap"><table><thead><tr><th>Stație</th><th>Procesare / blocat / idle</th><th>Procesare</th><th>Blocat</th><th>Coadă medie</th><th>+ produse la ciclu −20%</th></tr></thead><tbody>${r.stations.map(s=>`<tr><td>${esc(l.stations.find(x=>x.id===s.id).name)}</td><td><div class="bar"><i class="busy" style="width:${s.busy*100}%"></i><i class="blocked" style="width:${s.blocked*100}%"></i><i class="idle" style="width:${s.idle*100}%"></i></div></td><td>${fmt(s.busy*100,1)}%</td><td>${fmt(s.blocked*100,1)}%</td><td>${fmt(s.queue,1)}</td><td>${fmt(ranks[l.id]?.find(x=>x.id===s.id)?.gain)}</td></tr>`).join('')}</tbody></table></div></div><div class="grid2"><div class="panel"><h2>WIP în timp</h2>${chart(r)}</div><div class="panel"><h2>Auditul execuției</h2><p class="small">${fmt(r.arrived)} intrări = ${fmt(r.done)} finalizate + ${fmt(r.wip)} în sistem.</p><p class="small muted">Seed ${seed} · orizont ${hours} h · stare inițială goală · o replicare · fără warm-up. Unitatea de timp internă: secunda.</p><p class="small muted">Timpi uniformi între ciclu × (1 − variație) și ciclu × (1 + variație). Model necalibrat; fără intervale de încredere.</p></div></div>`}`}
function scenarios(){return `<div class="panel"><h2>Compară înainte să investești</h2><p class="muted">Salvează modelul și rezultatul actual ca baseline, modifică stațiile, apoi rulează din nou cu același orizont și seed.</p><div class="row"><button data-act="baseline" class="primary" ${result?'':'disabled'}>Fixează baseline</button><button data-act="restore" ${baseline?'':'disabled'}>Restaurează modelul baseline</button></div>${baseline?`<div class="notice">Baseline păstrat în memoria sesiunii. Exportă comparația pentru arhivare.</div><div class="tablewrap"><table><thead><tr><th>Indicator</th><th>Baseline</th><th>Scenariu actual</th><th>Diferență</th></tr></thead><tbody><tr><td>Produse finalizate</td><td>${fmt(baseline.result.done)}</td><td>${fmt(result?.done)}</td><td>${result?fmt(result.done-baseline.result.done):'—'}</td></tr><tr><td>WIP final</td><td>${fmt(baseline.result.wip)}</td><td>${fmt(result?.wip)}</td><td>${result?fmt(result.wip-baseline.result.wip):'—'}</td></tr></tbody></table></div><button data-act="comparison">↓ Export comparație JSON</button>`:'<div class="empty">Nu există încă un baseline.</div>'}</div><div class="panel"><h2>Estimare economică a intervenției</h2><p class="small muted">Introduce un beneficiu lunar net justificat prin cerere și costuri. Capacitatea suplimentară nu înseamnă automat vânzări.</p><div class="row"><label>Investiție € <input id="investment" type="number" min="0" value="15000"></label><label>Beneficiu net €/lună <input id="benefit" type="number" value="1000"></label><button data-act="payback">Calculează</button><strong id="payback"></strong></div></div>`}
function architecture(){return `<div class="notice">Profil MOFLT propriu, conform definiției tale. Nu reprezintă profilul Airbus și nici implementarea completă SysML/UAF.</div><div class="panel"><div class="panelhead"><h2>Mission → Operational → Functional → Logical → Technical</h2><button data-act="new-element">+ Element</button></div><div class="moflt">${[['M','Mission'],['O','Operational'],['F','Functional'],['L','Logical'],['T','Technical']].map(([level,name])=>`<div class="level"><h3>${level} <span class="muted small">${name}</span></h3>${model.elements.filter(e=>e.level===level).map(e=>`<div class="element">${esc(e.name)}<small>${esc(e.id)}</small></div>`).join('')}</div>`).join('')}</div></div><div class="panel"><div class="panelhead"><h2>Relații semantice</h2><button data-act="new-link">+ Relație</button></div><table><thead><tr><th>Sursă</th><th>Relație</th><th>Destinație</th><th></th></tr></thead><tbody>${model.links.map((l,i)=>`<tr><td>${esc(refName(l.from))}</td><td>${esc(l.type)}</td><td>${esc(refName(l.to))}</td><td><button data-unlink="${i}">Elimină</button></td></tr>`).join('')}</tbody></table></div>`}
function refs(){return [...model.elements,...model.lines.flatMap(l=>l.stations)]}function refName(id){return refs().find(e=>e.id===id)?.name||id}
function requirements(){return `<div class="panel"><div class="panelhead"><h2>Cerințe și alocări</h2><button data-act="new-req">+ Cerință</button></div><table><thead><tr><th>ID</th><th>Cerință</th><th>Trasabilitate</th><th></th></tr></thead><tbody>${model.requirements.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.text)}</td><td>${r.targets.map(t=>`<span class="pill">${esc(refName(t))}</span>`).join(' ')||'<span class="badge amber">Nealocată</span>'}</td><td><button data-reqdelete="${esc(r.id)}">Șterge</button></td></tr>`).join('')}</tbody></table></div><div class="notice">Ștergerea unei stații cu legături este blocată pentru a păstra trasabilitatea. Analiza automată de satisfacere a cerințelor nu este implementată.</div>`}
function safety(){return `<div class="notice">Registru calitativ de hazarduri. Nu calculează FTA/FMEA și nu stabilește acceptabilitatea riscului.</div><div class="panel"><div class="panelhead"><h2>Hazard register</h2><button data-act="new-hazard">+ Hazard</button></div><table><thead><tr><th>ID</th><th>Hazard</th><th>Măsură propusă</th><th>Stare</th></tr></thead><tbody>${model.hazards.map(h=>`<tr><td>${esc(h.id)}</td><td>${esc(h.text)}</td><td>${esc(h.mitigation)}</td><td><span class="badge amber">${esc(h.status)}</span></td></tr>`).join('')}</tbody></table></div>`}
function about(){return `<div class="grid2"><div class="panel"><h2>Funcțional în v0.1</h2><ul class="checklist"><li>Editor linii seriale, stații, capacități și buffere finite</li><li>DES în Web Worker cu blocking-after-service</li><li>Sensibilitate individuală la reducerea ciclului cu 20%</li><li>Baseline, scenarii, CSV rezultate și JSON model</li><li>MOFLT, legături și trasabilitate cerințe</li><li>Salvare în browser și undo/redo pentru model</li></ul></div><div class="panel"><h2>Etape următoare</h2><ul class="checklist"><li>Backend de echipă, conturi, revizii și audit</li><li>Rute ramificate, BOM, resurse partajate</li><li>Schimburi, defectări, setup și rework</li><li>Replicări statistice și calibrare</li><li>Optimizare scheduling și integrare OPC UA/MES</li><li>Profiluri UAF/TOGAF, SysML și ReqIF</li></ul></div></div><div class="panel"><h2>Metoda de lucru</h2><p>Structurare inspirată din ISA-95, analiză a fluxului prin Lean/VSM și investigarea constrângerilor prin TOC. Motor DES original JavaScript pentru acest prototip. Nu folosește încă SimPy sau OR-Tools.</p><p class="muted">Aplicația este găzduită web, dar datele modelului sunt salvate numai în browserul curent. Nu există sincronizare între colegi sau dispozitive. Exportul JSON este mecanismul de transfer și backup. Datele inițiale sunt fictive.</p><p class="muted">Liniile sunt independente. Limite de validare: 30 linii × maximum 50 stații, capacitate 1–20/stație, orizont maximum 168 h. Acestea sunt limite de intrare, nu performanță garantată pentru fabrici mari. Simulările foarte mari pot fi anulate.</p></div>`}
function render(){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">F</span> factory studio</div><div class="subtitle">SYSTEMS & FLOW</div><div class="navlabel">Workspace</div><nav>${Object.entries(names).map(([k,v],i)=>`<button class="nav ${page===k?'active':''}" data-page="${k}"><span>${navicons[i]}</span>${v}</button>`).join('')}</nav><footer><div><span class="avatar">VE</span>Engineering workspace</div><div class="small">v0.1 · prototip funcțional<br>Salvare locală în browser</div></footer></aside><main class="main"><header class="topbar"><div class="crumb">Workspace / <strong>${esc(model.name)}</strong></div><div class="actions"><button data-act="undo" aria-label="Undo" ${history.length&&!busy?'':'disabled'}>↶</button><button data-act="redo" aria-label="Redo" ${future.length&&!busy?'':'disabled'}>↷</button><button data-act="import">↑ Import</button><button data-act="export">↓ Export model</button></div></header><div class="workspace"><div class="headline"><div><div class="eyebrow">FACTORY INTELLIGENCE</div><h1>${names[page]}</h1><div class="statusline">${saveOK?'● Model local salvat':'⚠ Exportă modelul pentru backup'} · ${model.lines.length} linii · ${result?'rezultate simulate':'pregătit pentru simulare'}</div></div>${['overview','lines','simulation','scenarios'].includes(page)?controls():''}</div>${({overview,lines:editor,simulation,scenarios,architecture,requirements,safety,about}[page])()}</div></main></div><input hidden id="file" type="file" accept="application/json,.json">`;
if(page==='scenarios'&&baseline&&result&&(baseline.result.options.hours!==result.options.hours||baseline.result.options.seed!==result.options.seed)){
 const warning=document.createElement('div');warning.className='notice';warning.textContent='Atenție: orizontul sau seed-ul diferă de baseline. Diferențele afișate nu izolează efectul modificărilor de proiectare.';document.querySelector('.workspace').prepend(warning);
}
bind();}
function download(name,body,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function modal(title,html,save){const cover=document.createElement('div');cover.className='cover';cover.innerHTML=`<form class="dialog"><div class="panelhead"><h2>${title}</h2><button type="button" id="close">✕</button></div>${html}<div class="row"><button class="primary" type="submit">Salvează</button><button type="button" id="cancel">Anulează</button></div></form>`;document.body.append(cover);const close=()=>cover.remove();cover.querySelector('#close').onclick=close;cover.querySelector('#cancel').onclick=close;cover.querySelector('form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));close();save(data)};cover.querySelector('input,textarea,select')?.focus()}
function stationDialog(id){if(busy)return;const s=model.lines.flatMap(l=>l.stations).find(s=>s.id===id);modal('Proprietăți stație',`<label>Nume<input name="name" value="${esc(s.name)}" required maxlength="120"></label><div class="formgrid">${[['cycle','Ciclu (s)',1,86400,'.1'],['capacity','Resurse paralele',1,20,1],['buffer','Buffer intrare (piese)',1,1000,1],['variation','Variație uniformă ± (0–0.9)',0,.9,'.01']].map(([key,label,min,max,step])=>`<label>${label}<input name="${key}" type="number" min="${min}" max="${max}" step="${step}" value="${s[key]}" required></label>`).join('')}</div>`,d=>mutate(()=>Object.assign(s,{name:d.name,cycle:+d.cycle,capacity:+d.capacity,buffer:+d.buffer,variation:+d.variation})));}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});document.querySelectorAll('[data-line]').forEach(b=>b.onclick=()=>{selected=b.dataset.line;page='lines';render()});document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>stationDialog(b.dataset.edit));document.querySelectorAll('[data-act]').forEach(b=>b.onclick=()=>action(b.dataset.act));
 $('#line-select')?.addEventListener('change',e=>{selected=e.target.value;render()});
 for(const k of ['hours','seed'])$('#'+k)?.addEventListener('change',e=>{const v=+e.target.value;if(!Number.isFinite(v)||(k==='hours'?(v<.1||v>168):(!Number.isInteger(v)||v<0||v>2147483647))){toast('Valoare invalidă.');render();return}if(k==='hours')hours=v;else seed=v;result=null;ranks={};render()});
 document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{if(!busy)mutate(()=>{const ss=line().stations,i=ss.findIndex(s=>s.id===b.dataset.move),j=i+Number(b.dataset.dir);[ss[i],ss[j]]=[ss[j],ss[i]]})});
 document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(!busy)mutate(()=>{const id=b.dataset.delete;if(model.links.some(x=>x.from===id||x.to===id)||model.requirements.some(r=>r.targets.includes(id)))throw Error('Stația are legături. Elimină explicit alocările înainte de ștergere.');line().stations=line().stations.filter(s=>s.id!==id)})});
 document.querySelectorAll('[data-unlink]').forEach(b=>b.onclick=()=>{if(!busy)mutate(()=>model.links.splice(+b.dataset.unlink,1))});document.querySelectorAll('[data-reqdelete]').forEach(b=>b.onclick=()=>{if(!busy)mutate(()=>model.requirements=model.requirements.filter(r=>r.id!==b.dataset.reqdelete))});
 $('#file').onchange=async e=>{if(busy)return;const f=e.target.files[0];if(!f)return;if(f.size>5e6){toast('Fișier prea mare (max. 5 MB).');return}try{const imported=JSON.parse(await f.text());validate(imported);mutate(()=>{model=imported;selected=model.lines[0].id});toast('Model importat. Poți reveni prin Undo.')}catch(err){toast('Import respins: '+err.message)}};
}
function action(a){if(busy&&!['cancel','export','import'].includes(a)){toast('Așteaptă sau anulează simularea înainte de editare.');return}const uid=prefix=>prefix+'-'+crypto.randomUUID().slice(0,8);
 if(a==='run')return run();if(a==='cancel'){worker?.terminate();worker=null;busy=false;render();return}
 if(a==='export')return download('factory-model.json',JSON.stringify(model,null,2));if(a==='import')return $('#file').click();
 if(a==='undo'||a==='redo'){const from=a==='undo'?history:future,to=a==='undo'?future:history;if(from.length){to.push(structuredClone(model));model=from.pop();result=null;ranks={};persist();render()}return}
 if(a==='save-line')return mutate(()=>{line().name=$('#line-name').value;line().arrival=+$('#arrival').value});
 if(a==='new-line')return modal('Linie nouă','<label>Nume<input name="name" required maxlength="120"></label>',d=>mutate(()=>{const id=uid('line');model.lines.push({id,name:d.name,arrival:60,stations:[{id:uid('station'),name:'Operație 1',cycle:60,capacity:1,buffer:8,variation:0}]});selected=id}));
 if(a==='new-station')return mutate(()=>line().stations.push({id:uid('station'),name:'Operație '+(line().stations.length+1),cycle:60,capacity:1,buffer:8,variation:0}));
 if(a==='baseline'){baseline={model:structuredClone(model),result:structuredClone(result)};render();return}
 if(a==='restore'&&baseline)return mutate(()=>{model=structuredClone(baseline.model);hours=baseline.result.options.hours;seed=baseline.result.options.seed});
 if(a==='comparison')return download('factory-comparison.json',JSON.stringify({baseline,current:{model,result},comparable:!!result&&result.options.hours===baseline.result.options.hours&&result.options.seed===baseline.result.options.seed},null,2));
 if(a==='payback'){const inv=+$('#investment').value,b=+$('#benefit').value;$('#payback').textContent=inv<0||!Number.isFinite(inv)||!Number.isFinite(b)?'Valori invalide':b>0?`${fmt(inv/b,1)} luni · cash-flow constant`:'Investiția nu se recuperează cu acest beneficiu';return}
 if(a==='csv'){const r=lr(line().id);const cell=x=>'"'+String(x).replaceAll('"','""')+'"';return download('station-results.csv','\ufeff'+[['station_id','processing_percent','blocked_percent','idle_percent','average_queue','completed'],...r.stations.map(s=>[s.id,s.busy*100,s.blocked*100,s.idle*100,s.queue,s.count])].map(row=>row.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
 if(a==='new-element')return modal('Element MOFLT','<label>Nume<input name="name" required maxlength="150"></label><label>Nivel<select name="level">'+['M','O','F','L','T'].map(x=>`<option>${x}</option>`).join('')+'</select></label>',d=>mutate(()=>model.elements.push({id:uid(d.level),...d})));
 const options=refs().map(e=>`<option value="${esc(e.id)}">${esc(e.name)} (${esc(e.id)})</option>`).join('');
 if(a==='new-link')return modal('Relație semantică',`<label>Sursă<select name="from">${options}</select></label><label>Relație<select name="type"><option>allocated to</option><option>realized by</option><option>maps to station</option><option>depends on</option></select></label><label>Destinație<select name="to">${options}</select></label>`,d=>mutate(()=>{if(d.from===d.to)throw Error('Selectează elemente diferite.');model.links.push(d)}));
 if(a==='new-req')return modal('Cerință și trasabilitate',`<label>Cerință<textarea name="text" required maxlength="1000"></textarea></label><label>Alocare inițială<select name="target"><option value="">Nealocată</option>${options}</select></label>`,d=>mutate(()=>model.requirements.push({id:uid('REQ'),text:d.text,targets:d.target?[d.target]:[]})));
 if(a==='new-hazard')return modal('Hazard nou','<label>Hazard<textarea name="text" required maxlength="1000"></textarea></label><label>Măsură propusă<textarea name="mitigation" required maxlength="1000"></textarea></label><label>Stare<select name="status"><option>Open</option><option>Mitigated</option><option>Accepted</option></select></label>',d=>mutate(()=>model.hazards.push({id:uid('HAZ'),...d})));
}
persist();render();
